use crate::{Story, StoryError};

pub fn apply(story: &mut Story) -> Result<(), StoryError> {
    matthew(story)?;
    mark(story)?;
    luke(story)?;
    john(story)?;
    acts(story)?;
    Ok(())
}

fn matthew(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "Matthew", 1, "Matthew opens with a genealogy that threads kings, outsiders, and unlikely ancestors into one long dependency chain.", "Joseph receives a dream-message, keeps Mary's honor intact, and accepts the child as a name-bearing promise.");
    crate::chapter!(story, "Matthew", 2, "Magi arrive with release-day gifts, while Herod treats a newborn rumor like a threat to his throne's ownership.", "The family flees, returns after danger clears, and settles in Nazareth after several tense migrations.");
    crate::chapter!(story, "Matthew", 3, "John the Baptist runs a wilderness deployment, calling for changed lives and warning that empty branches will be pruned.", "Jesus enters the river, and the heavens identify him as the beloved Son before his public mission begins.");
    crate::chapter!(story, "Matthew", 4, "In the wilderness Jesus rejects shortcuts offered by the tempter, choosing trust over spectacular demonstrations.", "He announces God's reign, calls fishermen into a new team, and heals crowds whose brokenness has no single bug report.");
    crate::chapter!(story, "Matthew", 5, "Jesus blesses the poor, grieving, meek, hungry, merciful, pure, peacemaking, and persecuted as citizens of a surprising kingdom.", "He makes his followers salt and light, then deepens the law from outward compliance into the heart's source code.");
    crate::chapter!(story, "Matthew", 6, "Jesus audits generosity, prayer, and fasting, asking for quiet integrity instead of public metrics.", "He teaches a compact prayer, warns against hoarding, and tells anxious hearts to seek God's kingdom before tomorrow's backlog.");
    crate::chapter!(story, "Matthew", 7, "The sermon turns toward discernment: remove the beam from your own eye before reviewing a neighbor's tiny lint warning.", "Wise builders practice Jesus' words, while false prophets and empty claims fail when the storm reaches production.");
    crate::chapter!(story, "Matthew", 8, "Jesus heals a leper, a centurion's servant, and Peter's mother-in-law, showing mercy crossing social and geographic boundaries.", "He stills a storm and frees tormented men, proving that even wind and hostile processes answer to his authority.");
    crate::chapter!(story, "Matthew", 9, "A paralyzed man receives forgiveness and movement, while Jesus calls Matthew and eats with people respectable systems had rejected.", "He restores a girl, a bleeding woman, two blind men, and a mute sufferer, then sees the crowds as a harvest needing workers.");
    crate::chapter!(story, "Matthew", 10, "Jesus commissions the twelve with healing authority, a travel kit of trust, and a warning that the mission will meet resistance.", "They must be wise under pressure, faithful before governors, and willing to lose comfort while carrying the kingdom's message.");
    crate::chapter!(story, "Matthew", 11, "John asks from prison whether Jesus is truly the awaited one, and Jesus points to restored lives rather than flashy credentials.", "He praises John's role, exposes fickle crowds, and invites the burdened to learn his gentle way of carrying the load.");
    crate::chapter!(story, "Matthew", 12, "Jesus defends hungry disciples on the Sabbath and heals a withered hand, insisting that mercy outranks a brittle rule engine.", "He answers accusations about dark power, warns about careless words, and names obedient hearers as his true family.");
    crate::chapter!(story, "Matthew", 13, "Jesus deploys parables: seed on varied soil, weeds among wheat, a mustard seed, hidden treasure, and a pearl worth everything.", "The kingdom appears small and mixed for now, yet its final sorting and value exceed what the first log lines reveal.");
    crate::chapter!(story, "Matthew", 14, "Herod's banquet ends with John's execution, a grim record of power protecting its own impulsive promises.", "Jesus feeds five thousand, walks across the waves, and steadies Peter's brief borrowed courage amid the storm.");
    crate::chapter!(story, "Matthew", 15, "Jesus distinguishes tradition from the heart's actual output, locating defilement in destructive desires rather than unwashed hands.", "A Canaanite woman's persistent trust receives mercy, and another crowd is fed after days in the open countryside.");
    crate::chapter!(story, "Matthew", 16, "Jesus warns about the yeast of religious performance, then asks the disciples who they believe he is.", "Peter confesses the Messiah, but resists the cross; Jesus rebukes that shortcut and calls followers to deny self and take up sacrifice.");
    crate::chapter!(story, "Matthew", 17, "Jesus is transfigured before Peter, James, and John, with Moses and Elijah appearing as witnesses to his identity.", "After healing a tormented boy, he predicts his death again and teaches temple-tax humility through a fish and a coin.");
    crate::chapter!(story, "Matthew", 18, "Jesus places a child in the center and teaches that greatness looks like humble care for the vulnerable.", "He gives a process for confronting harm, tells of a lost sheep, and contrasts forgiven debt with a servant who refuses to forgive.");
    crate::chapter!(story, "Matthew", 19, "Jesus blesses children, challenges easy divorce logic, and treats covenant faithfulness as more than a convenient configuration.", "A wealthy seeker walks away from radical generosity, while Jesus promises that surrendered lives will not be forgotten.");
    crate::chapter!(story, "Matthew", 20, "The vineyard owner pays late workers the same generous wage, upsetting the accounting instincts of those who arrived first.", "Jesus predicts the cross, heals two blind men, and defines leadership as serving rather than claiming the highest seat.");
    crate::chapter!(story, "Matthew", 21, "Jesus enters Jerusalem on a humble mount, receives public praise, and cleanses the temple of commerce that has displaced prayer.", "A withered fig tree becomes a warning about fruitless confidence, followed by parables that expose leaders rejecting God's messenger.");
    crate::chapter!(story, "Matthew", 22, "A wedding feast fills with unexpected guests, while one unprepared attendee learns that invitation and response belong together.", "Jesus answers traps about taxes, resurrection, and the greatest commandment, then asks how the Messiah can be both David's son and Lord.");
    crate::chapter!(story, "Matthew", 23, "Jesus denounces leaders who love visible status while loading others with burdens they will not carry themselves.", "He names hypocrisy in precise, painful terms and laments Jerusalem as a house that keeps refusing the shelter it needs.");
    crate::chapter!(story, "Matthew", 24, "Jesus predicts the temple's collapse and warns disciples not to confuse disasters, rumors, or impostors with the final arrival.", "The faithful servant stays awake and responsible because the timing is hidden, not because vigilance is optional.");
    crate::chapter!(story, "Matthew", 25, "Ten bridesmaids wait through a delayed arrival; only the prepared lamps are ready when the midnight call finally comes.", "Talents are entrusted for active stewardship, and the final judgment measures how people treated the hungry, stranger, sick, imprisoned, and overlooked.");
    crate::chapter!(story, "Matthew", 26, "Religious leaders scheme, a woman pours costly perfume, Judas negotiates betrayal, and Jesus shares a covenant meal before the crisis.", "In Gethsemane he prays through dread, is arrested, and faces witnesses who cannot make their conflicting testimony compile.");
    crate::chapter!(story, "Matthew", 27, "Judas returns the silver in despair, while Pilate hands Jesus over despite recognizing the political case as hollow.", "Jesus is mocked, crucified, buried in a guarded tomb, and sealed beneath the authorities' best attempt at finality.");
    crate::chapter!(story, "Matthew", 28, "At dawn the tomb is found open, and the risen Jesus meets women who become the first witnesses of the new release.", "He sends his followers to all peoples, promising his continuing presence as they teach and baptize.");
    Ok(())
}

fn mark(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "Mark", 1, "Mark begins at full speed with John's wilderness call, Jesus' baptism, and a forty-day test before public work launches.", "Fishermen are called, a synagogue spirit is silenced, and healings spread through Capernaum until even solitude requires deliberate scheduling.");
    crate::chapter!(story, "Mark", 2, "Friends lower a paralyzed man through a roof, and Jesus heals him while also asserting authority to forgive sins.", "He calls Levi, eats with outsiders, and explains that Sabbath and fasting belong to a living mission rather than dead maintenance.");
    crate::chapter!(story, "Mark", 3, "Jesus restores a man's hand on the Sabbath, drawing both admiration and a plot from systems threatened by mercy.", "He appoints twelve companions, answers the Beelzebul accusation, and names those who do God's will as his real household.");
    crate::chapter!(story, "Mark", 4, "Jesus teaches from a boat with stories of seed, lamp-light, growing crops, and a mustard seed that starts tiny but becomes shelter.", "He calms a storm, leaving the disciples to ask what kind of person can command the sea and receive obedience.");
    crate::chapter!(story, "Mark", 5, "A man possessed by a legion of destructive voices is restored to his right mind, though the local economy prefers the old arrangement.", "Jesus heals a long-suffering woman and raises Jairus's daughter, showing life returning in both public and intimate spaces.");
    crate::chapter!(story, "Mark", 6, "Nazareth takes offense at Jesus, and he sends the twelve in pairs with minimal luggage and maximum dependence on hospitality.", "John is executed at Herod's banquet; Jesus feeds five thousand, walks on water, and heals wherever people reach for him.");
    crate::chapter!(story, "Mark", 7, "Jesus challenges hand-washing traditions that conceal corrupt hearts and teaches that inner output, not ritual input, makes a person unclean.", "He heals a Gentile woman's daughter and a deaf man with a speech impediment, opening ears and loosening tongues.");
    crate::chapter!(story, "Mark", 8, "A second crowd is fed, but the disciples still confuse bread logistics with the deeper warning about hardened understanding.", "Peter identifies Jesus as the Messiah; Jesus predicts suffering, rebukes shortcut thinking, and calls the crowd to carry a cross-shaped life.");
    crate::chapter!(story, "Mark", 9, "Jesus shines on the mountain while Moses and Elijah appear, then descends to a failed exorcism and heals a boy everyone else could not free.", "He teaches about servant greatness, welcoming the little ones, and removing whatever repeatedly makes a life stumble.");
    crate::chapter!(story, "Mark", 10, "Jesus teaches covenant faithfulness, welcomes children, and tells a wealthy man that possessions can become a locked gate.", "He predicts the cross, corrects the disciples' ambition, and gives sight to Bartimaeus, whose persistent call becomes a model of trust.");
    crate::chapter!(story, "Mark", 11, "Jesus enters Jerusalem, curses a leafy but fruitless fig tree, and clears the temple of commerce that has crowded out prayer.", "He teaches about faith, forgiveness, and authority while the religious officials circle him with questions designed as traps.");
    crate::chapter!(story, "Mark", 12, "The vineyard tenants reject the owner's son, and Jesus uses the story to expose leaders who mistake stewardship for ownership.", "He answers questions about taxes and resurrection, names love of God and neighbor as central, and praises a widow's two small coins.");
    crate::chapter!(story, "Mark", 13, "Jesus foretells the temple's ruin and describes turmoil, persecution, false messiahs, and cosmic signs without giving a timetable.", "The repeated command is watchfulness: servants should keep doing their assigned work because the returning master may arrive unseen.");
    crate::chapter!(story, "Mark", 14, "A woman anoints Jesus, Judas agrees to betray him, and the disciples share a final meal marked by bread, cup, and a warning.", "Prayer in Gethsemane gives way to arrest, desertion, a torn high-priestly courtroom, and Peter's three denials before the rooster log.");
    crate::chapter!(story, "Mark", 15, "Pilate yields Jesus to the crowd, soldiers mock him, and Simon of Cyrene is pulled into the procession toward Golgotha.", "Jesus dies on the cross, the temple curtain tears, and Joseph of Arimathea places him in a rock-cut tomb before the Sabbath begins.");
    crate::chapter!(story, "Mark", 16, "Women arrive with burial spices and find the stone rolled away, receiving the startling news that Jesus has risen and gone ahead.", "The witnesses leave trembling wonder, and the risen Lord's mission spreads through signs, proclamation, and the disciples' continued work.");
    Ok(())
}

fn luke(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "Luke", 1, "Luke addresses an orderly investigation, then contrasts Gabriel's announcements to Zechariah and Mary as two responses to impossible news.", "Mary visits Elizabeth, sings a reversal-filled praise song, and John is born before Zechariah's restored speech blesses the coming dawn.");
    crate::chapter!(story, "Luke", 2, "A census moves Joseph and Mary to Bethlehem, where Jesus is born among ordinary animals and announced to startled shepherds.", "Simeon and Anna recognize the child at the temple, and the young Jesus later remains there discussing his Father's business.");
    crate::chapter!(story, "Luke", 3, "John calls the crowds to practical repentance, demanding shared clothing, honest taxes, and no abuse of power.", "Jesus is baptized, the Spirit descends, and Luke traces his genealogy backward through generations to Adam.");
    crate::chapter!(story, "Luke", 4, "Jesus rejects wilderness temptations, reads Isaiah in Nazareth, and announces good news that the hometown crowd does not want universalized.", "He frees a demonized man, heals Simon's mother-in-law, and departs before dawn to preach in other towns.");
    crate::chapter!(story, "Luke", 5, "A miraculous catch turns fishermen into disciples, while a leper and a paralyzed man receive cleansing and forgiveness.", "Jesus calls Levi from the tax desk, eats with sinners, and explains why new wine requires containers able to change.");
    crate::chapter!(story, "Luke", 6, "Jesus defends hungry disciples and heals on the Sabbath, revealing the Son of Man as master of a mercy-shaped day.", "He chooses the twelve, blesses the poor and persecuted, teaches enemy-love, and compares hearers to builders whose foundations are tested.");
    crate::chapter!(story, "Luke", 7, "A centurion's trust and a widow's restored son display authority that heals from a distance and compassion that interrupts funerals.", "John asks from prison, a sinful woman anoints Jesus' feet with tears, and forgiveness becomes visible in extravagant love.");
    crate::chapter!(story, "Luke", 8, "Women support Jesus' mission, and the parable of the sower explains why the same word produces different harvests.", "Jesus calms a storm, frees a Gerasene man, heals a bleeding woman, and raises Jairus's daughter from death.");
    crate::chapter!(story, "Luke", 9, "The twelve are sent, five thousand are fed, and Peter confesses Jesus as God's Messiah after a long day of signs.", "The transfiguration, a failed exorcism, and lessons about servant greatness lead toward Jerusalem, where following requires undivided resolve.");
    crate::chapter!(story, "Luke", 10, "Seventy-two messengers return from a broad mission, and Jesus rejoices that God's kingdom is revealed to the humble.", "The Good Samaritan answers a lawyer's boundary question, while Martha and Mary show two different kinds of attention at Jesus' feet.");
    crate::chapter!(story, "Luke", 11, "Jesus teaches persistent prayer with a midnight friend, a child's request, and a father who gives good gifts rather than stones.", "He answers accusations about demons, warns against a cleaned but empty interior, and confronts experts who burden others with religious knowledge.");
    crate::chapter!(story, "Luke", 12, "Jesus warns against hypocrisy, greed, and anxiety, using a foolish rich farmer whose storage plan cannot purchase another breath.", "Servants are told to stay ready, households are warned about division, and the crowd is urged to read the present moment honestly.");
    crate::chapter!(story, "Luke", 13, "Jesus calls for repentance without pretending that every tragedy has a simple cause, then heals a bent woman on the Sabbath.", "Stories of a mustard seed and yeast describe hidden growth, while the narrow door and Jerusalem's rejected welcome press urgency into the lesson.");
    crate::chapter!(story, "Luke", 14, "Jesus heals on the Sabbath and teaches guests to choose the lower place rather than reserving honor in advance.", "A great banquet is refused by people with competing schedules, and discipleship is measured by willingness to bear a costly cross.");
    crate::chapter!(story, "Luke", 15, "A lost sheep and lost coin trigger joy when found, revealing heaven's celebration over one recovered life.", "The returning younger son is welcomed, while the resentful elder brother must decide whether grace can belong outside his accounting system.");
    crate::chapter!(story, "Luke", 16, "A shrewd manager prepares for the future by using present resources, and Jesus turns the tale toward trustworthy stewardship.", "The rich man and Lazarus expose a reversal too late for negotiation, with a chasm wider than any postmortem appeal.");
    crate::chapter!(story, "Luke", 17, "Jesus teaches against causing others to stumble, calls for repeated forgiveness, and heals ten lepers while only one returns with thanks.", "He describes God's kingdom as already among people and warns that the Son of Man's revealing will be sudden and impossible to schedule.");
    crate::chapter!(story, "Luke", 18, "A persistent widow wears down an unjust judge, while a Pharisee and tax collector reveal the difference between self-display and humble prayer.", "Jesus welcomes children, challenges a rich ruler, predicts the cross, and restores sight to a blind man who refuses to be silenced.");
    crate::chapter!(story, "Luke", 19, "Zacchaeus responds to Jesus by repairing financial harm, and the parable of entrusted money tests what servants do while the king is away.", "Jesus enters Jerusalem, weeps over it, and clears the temple before teaching daily in the place that should have been a house of prayer.");
    crate::chapter!(story, "Luke", 20, "Religious authorities question Jesus' authority, and he answers with the vineyard tenants who reject the owner's beloved son.", "Taxes, resurrection, and scribal status are examined, ending with a widow whose tiny offering outshines the large public deposits.");
    crate::chapter!(story, "Luke", 21, "The widow's offering becomes a lesson in costly generosity, followed by warnings about the temple's fall, wars, persecution, and cosmic shaking.", "Jesus tells disciples to stay awake and pray so they can stand steady when the world's familiar interface begins to fail.");
    crate::chapter!(story, "Luke", 22, "The Passover meal becomes a covenant sign, Judas joins the betrayal plan, and the disciples argue about which of them is greatest.", "Jesus prays on the Mount of Olives, is arrested, questioned, denied by Peter, and handed from council to council as dawn approaches.");
    crate::chapter!(story, "Luke", 23, "Pilate and Herod find no solid charge yet still surrender Jesus to the crowd's demand for execution.", "Jesus forgives from the cross, promises paradise to a repentant criminal, dies, and is buried by Joseph while women prepare spices for after the Sabbath.");
    crate::chapter!(story, "Luke", 24, "Women find the tomb empty, two travelers meet the risen Jesus on the road, and their recognition arrives through opened scriptures and broken bread.", "Jesus appears to the gathered disciples, commissions witness from Jerusalem outward, and ascends while blessing them.");
    Ok(())
}

fn john(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "John", 1, "John presents the Word as the source of life and light, entering human history without being owned by the darkness.", "John the Baptist points away from himself, Andrew and others follow Jesus, and Nathanael joins after a promise to see greater things.");
    crate::chapter!(story, "John", 2, "At Cana Jesus turns a wedding shortage into abundant celebration, and his first sign reveals glory through ordinary hospitality.", "He clears the temple, speaks of a sanctuary raised after destruction, and refuses to hand his trust to crowds impressed by signs alone.");
    crate::chapter!(story, "John", 3, "Nicodemus visits at night and learns that new life requires birth from above, not merely an improved religious configuration.", "John the Baptist gladly yields attention to Jesus, comparing himself to the friend who hears the bridegroom and rejoices.");
    crate::chapter!(story, "John", 4, "Jesus speaks with a Samaritan woman at a well, offering living water and exposing her history without turning the conversation into contempt.", "Many Samaritans believe, and a royal official's son is healed at a distance when the father trusts Jesus' word.");
    crate::chapter!(story, "John", 5, "At Bethesda Jesus restores a man who has been unable to walk and then explains that the Father's life-giving work continues through him.", "The authorities object to Sabbath healing, while Jesus appeals to witness from John, his works, the Father, and the scriptures.");
    crate::chapter!(story, "John", 6, "Jesus feeds five thousand and crosses the sea amid wind, but the crowd mainly wants another free meal.", "He calls himself the bread of life, speaks of eating and drinking as radical participation, and watches many followers withdraw.");
    crate::chapter!(story, "John", 7, "Jesus goes to the festival privately, teaches publicly, and divides the crowd over whether his origin can fit their assumptions.", "Temple officers return empty-handed, Nicodemus asks for fair process, and the authorities' certainty fractures into competing voices.");
    crate::chapter!(story, "John", 8, "Jesus refuses a trap involving an accused woman, turning the courtroom toward self-examination before condemnation.", "He calls himself the world's light, promises freedom from sin's ownership, and clashes with opponents who claim ancestry while rejecting truth.");
    crate::chapter!(story, "John", 9, "Jesus gives sight to a man blind from birth, making a living sign that cannot be deleted from the neighborhood record.", "The healed man is interrogated and expelled, yet his testimony grows clearer while the religious investigators become the truly blind party.");
    crate::chapter!(story, "John", 10, "Jesus describes himself as the shepherd whose voice is known, whose sheep are protected, and whose life is given rather than seized.", "A festival dispute follows, and Jesus declares unity with the Father before escaping an attempted stoning.");
    crate::chapter!(story, "John", 11, "Lazarus dies while Jesus delays, then Jesus calls him from the tomb and reveals resurrection life in the middle of mourning.", "The sign convinces many but intensifies the leaders' plot, turning restored life into the trigger for a final hostile deployment.");
    crate::chapter!(story, "John", 12, "Mary anoints Jesus at Bethany, Judas objects over cost, and Lazarus's presence draws a crowd the authorities want erased.", "Jesus enters Jerusalem, speaks of a grain of wheat dying to bear fruit, and announces judgment on the world's present ruler.");
    crate::chapter!(story, "John", 13, "Jesus washes the disciples' feet, converting leadership into embodied service and giving them a new command shaped by his love.", "Judas leaves into the night, Peter's confidence is corrected, and Jesus prepares friends for the grief of his departure.");
    crate::chapter!(story, "John", 14, "Jesus comforts troubled disciples with a promise of prepared belonging and identifies himself as the route to the Father.", "He promises the Advocate, teaches that love keeps his words, and offers peace unlike the world's fragile status reports.");
    crate::chapter!(story, "John", 15, "Jesus is the vine and the disciples are branches: fruit comes from remaining connected, not from independent spiritual heroics.", "He commands mutual love, warns that the world may hate his followers, and promises the Spirit as a continuing witness.");
    crate::chapter!(story, "John", 16, "Jesus explains that sorrow will turn to joy, like a woman whose labor pain gives way to the joy of a child arriving.", "The Spirit will guide, expose, and glorify; the disciples will scatter, yet Jesus claims a peace stronger than the world's trouble.");
    crate::chapter!(story, "John", 17, "Jesus prays for his own glory through faithful completion, for the disciples' protection, and for their unity in a hostile world.", "He extends the prayer to future believers, asking that shared love make the mission's truth visible rather than merely argued.");
    crate::chapter!(story, "John", 18, "Jesus is arrested in a garden, and his spoken identity makes the arresting party step back before he gives himself over.", "Peter denies him, Jesus faces Annas and Caiaphas, and Pilate questions a kingdom that does not operate by ordinary weapons.");
    crate::chapter!(story, "John", 19, "Pilate presents the mocked king, then yields to crucifixion while soldiers divide garments and Jesus completes his final charge.", "Jesus dies, is pierced, and is buried by Joseph and Nicodemus in a new tomb before the Sabbath deadline.");
    crate::chapter!(story, "John", 20, "Mary finds the stone moved, mistakes the risen Jesus for a gardener, and recognizes him when he calls her by name.", "Jesus appears behind locked doors, gives peace and the Spirit, and later meets Thomas whose doubt becomes a direct confession.");
    crate::chapter!(story, "John", 21, "The disciples catch nothing until Jesus directs the net, then share breakfast beside a charcoal fire and a miraculous haul.", "Jesus restores Peter with three questions about love and entrusts him with care, while hinting at the distinct paths of different disciples.");
    Ok(())
}

fn acts(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "Acts", 1, "The risen Jesus teaches about God's kingdom, promises the Spirit, and ascends while the apostles remain watching the sky.", "The community prays, consults scripture, and selects Matthias to join the restored circle of twelve witnesses.");
    crate::chapter!(story, "Acts", 2, "At Pentecost the Spirit arrives with wind and fire, and frightened disciples speak across language boundaries.", "Peter interprets the event, thousands respond, and the new community shares teaching, meals, prayers, and possessions with startling generosity.");
    crate::chapter!(story, "Acts", 3, "Peter and John meet a man unable to walk at the temple gate and offer healing in Jesus' name rather than a small cash patch.", "The amazed crowd hears Peter connect the sign to repentance, restoration, and the promise carried through Israel's story.");
    crate::chapter!(story, "Acts", 4, "The healed man brings the apostles before the council, where they refuse to stop speaking about Jesus' resurrection.", "The believers pray for boldness, share resources so none are abandoned, and watch Barnabas turn a field into communal provision.");
    crate::chapter!(story, "Acts", 5, "Ananias and Sapphira conceal part of a gift and discover that the community cannot be safely managed by deceptive accounting.", "Apostles heal publicly, survive imprisonment through an angelic release, and are beaten yet continue teaching in the temple.");
    crate::chapter!(story, "Acts", 6, "A distribution dispute exposes neglected widows, so the community appoints seven trusted servants to protect both fairness and prayer.", "Stephen's grace and wisdom provoke opposition, and false witnesses prepare the case that will make him the first martyr.");
    crate::chapter!(story, "Acts", 7, "Stephen retells Israel's story as a long pattern of resisting the deliverers God sends, from Joseph and Moses to the prophets.", "He sees the Son of Man in heavenly glory, is stoned while praying for his killers, and leaves Saul guarding the coats.");
    crate::chapter!(story, "Acts", 8, "Persecution scatters believers, and Philip brings joyful news to Samaria before confronting Simon's attempt to purchase spiritual authority.", "Philip explains Isaiah to an Ethiopian official, baptizes him, and is carried onward while the new believer continues rejoicing.");
    crate::chapter!(story, "Acts", 9, "Saul's road to Damascus becomes a total ownership transfer when the risen Jesus confronts the persecutor and redirects his mission.", "Ananias restores Saul's sight, Saul preaches, Peter heals Aeneas, and Tabitha is raised through the prayer of the gathered church.");
    crate::chapter!(story, "Acts", 10, "Cornelius receives a vision, Peter receives a rooftop vision about clean and unclean boundaries, and the two obey difficult instructions.", "The Spirit falls on Gentiles while Peter speaks, proving that God's welcome cannot be fenced by inherited access controls.");
    crate::chapter!(story, "Acts", 11, "Peter defends the Gentile inclusion before Jerusalem, explaining that the Spirit arrived before his old categories could finish objecting.", "Antioch becomes a major teaching center, and disciples are first called Christians there during a season of prophetic famine warnings.");
    crate::chapter!(story, "Acts", 12, "Herod executes James and imprisons Peter, but an angel leads Peter through locked gates while the church prays in one persistent room.", "Herod accepts divine honors and dies under judgment, while God's word keeps multiplying despite the ruler's attempt to stop the process.");
    crate::chapter!(story, "Acts", 13, "The Antioch church sends Barnabas and Saul after prayer and fasting, beginning a mission shaped by the Spirit's call rather than private ambition.", "In Pisidian Antioch Paul preaches Israel's story fulfilled in Jesus, meets both welcome and rejection, and turns toward the Gentiles.");
    crate::chapter!(story, "Acts", 14, "Paul and Barnabas heal a man in Lystra, are mistaken for gods, and then barely survive when the crowd reverses its opinion.", "They strengthen new disciples, appoint elders, and return to Antioch reporting that opened doors often include serious trouble.");
    crate::chapter!(story, "Acts", 15, "The Jerusalem council debates whether Gentile believers must inherit the full Jewish boundary markers before belonging.", "After testimony from Peter, Paul, Barnabas, and James, the church sends a concise letter of welcome and practical guidance.");
    crate::chapter!(story, "Acts", 16, "Paul receives a Macedonian vision, recruits Timothy, and meets Lydia, whose household becomes a base for the mission.", "A fortune-telling slave is freed, Paul and Silas sing in prison, and an earthquake opens doors before the jailer asks how to be saved.");
    crate::chapter!(story, "Acts", 17, "In Thessalonica and Berea, Paul reasons from scripture while crowds and rival claims turn the mission into a civic disturbance.", "At Athens he speaks of the unknown altar, presents the Creator without temple confinement, and announces resurrection to a divided audience.");
    crate::chapter!(story, "Acts", 18, "Paul works with Aquila and Priscilla in Corinth, teaches through opposition, and receives reassurance to keep speaking.", "Apollos learns a more complete account from the couple, showing that strong preaching can still need a careful dependency update.");
    crate::chapter!(story, "Acts", 19, "In Ephesus new disciples receive fuller teaching and the Spirit, while extraordinary healings expose the limits of borrowed formulas.", "A failed exorcism and a riot over the collapsing idol trade show the gospel challenging both spiritual presumption and profitable superstition.");
    crate::chapter!(story, "Acts", 20, "Paul raises Eutychus after a long night teaching, then travels toward Jerusalem with the urgency of someone who knows the route is costly.", "At Miletus he says farewell to Ephesian elders, warning them about false teachers and entrusting them to God's grace.");
    crate::chapter!(story, "Acts", 21, "Prophets warn Paul about Jerusalem, but he continues, accepting chains as part of the mission's ownership contract.", "He reports among believers, enters the temple, and is seized after a rumor sparks a riot the Roman commander must interrupt.");
    crate::chapter!(story, "Acts", 22, "Paul tells the crowd how the risen Jesus met him on the Damascus road and turned persecution into apostolic service.", "The crowd erupts when he mentions Gentiles, and the commander discovers too late that beating a Roman citizen is an expensive error.");
    crate::chapter!(story, "Acts", 23, "Paul faces the council, calls out a divided hearing, and survives when Pharisees and Sadducees split over resurrection.", "A nephew learns of an assassination plot, and the commander transfers Paul under heavy escort to Governor Felix in Caesarea.");
    crate::chapter!(story, "Acts", 24, "Tertullus accuses Paul before Felix, but Paul's defense joins resurrection hope with a clear conscience before God and people.", "Felix delays judgment while hoping for money, listens repeatedly with Drusilla, and leaves Paul confined when political convenience wins.");
    crate::chapter!(story, "Acts", 25, "Festus inherits the case, hears Jewish accusations, and refuses to send Paul to Jerusalem for a planned ambush.", "Paul appeals to Caesar, and King Agrippa arrives so Festus can explain a puzzling prisoner whose controversy centers on a risen Jesus.");
    crate::chapter!(story, "Acts", 26, "Paul gives Agrippa a personal and prophetic account, describing the heavenly commission that sent him from darkness toward light.", "The court finds no capital offense, yet the appeal stands, turning Paul's testimony into a passport for the next stage.");
    crate::chapter!(story, "Acts", 27, "The voyage toward Rome meets violent weather, and Paul receives assurance that every life aboard will survive the wreck.", "The ship breaks on Malta after disciplined action, shared food, and a final swim or plank carried the passengers through the storm.");
    crate::chapter!(story, "Acts", 28, "On Malta Paul survives a snakebite, heals the island official's father, and becomes a channel of mercy to many sick people.", "In Rome he welcomes visitors, reasons from scripture, and proclaims God's kingdom with unhindered boldness under house arrest.");
    Ok(())
}
